HUNT_MODE = 0                           -- the seed's Monster Hunt Checks: 0 off, 1 types, 2 every enemy

local defeated = {}                     -- enemy -> true, from the FFCC client
local marks = {}                        -- enemy -> true, marked by clicking
local cards = {}                        -- enemy -> item

-- true if any of the enemy type's pins can be reached (in logic)
local function reachable(enemy)
    for _, ref in ipairs(HUNT_SECTIONS[enemy] or {}) do
        local section = Tracker:FindObjectForCode(ref)
        local level = section and section.AccessibilityLevel
        if level == AccessibilityLevel.Normal or level == AccessibilityLevel.Cleared then
            return true
        end
    end
    return false
end

local refreshing = false                -- HuntRefresh changes items, which can call it again
local shown = {}                        -- enemy -> icon path on its card now

function HuntRefresh()
    if refreshing then return end
    refreshing = true
    for _, info in ipairs(HUNT_ENEMIES) do
        local item = cards[info.name]
        local done = defeated[info.name] == true
        local state = done and " (defeated)" or marks[info.name] and " (marked)" or ""
        local icon = info.card
        if state == "" then
            local open = reachable(info.name)
            icon = open and info.open or info.closed
            state = open and " (in logic)" or " (out of logic)"
        end
        local name = info.name .. state .. " - " .. info.where
        if item.Name ~= name then item.Name = name end
        if shown[info.name] ~= icon then
            item.Icon = ImageReference:FromPackRelativePath(icon)
            shown[info.name] = icon
        end
    end
    -- Enemy Types: a defeated (or marked) type clears all of its pins
    if HUNT_MODE == 1 then
        for enemy, refs in pairs(HUNT_SECTIONS) do
            local count = (defeated[enemy] or marks[enemy]) and 0 or 1
            for _, ref in ipairs(refs) do
                local section = Tracker:FindObjectForCode(ref)
                if section and section.AvailableChestCount ~= count then
                    section.AvailableChestCount = count
                end
            end
        end
    end
    refreshing = false
end

for _, info in ipairs(HUNT_ENEMIES) do
    local item = ScriptHost:CreateLuaItem()
    local name = info.name
    item.Name = name
    item.Icon = ImageReference:FromPackRelativePath(info.card)
    item.CanProvideCodeFunc = function(self, wanted) return wanted == info.code end
    item.ProvidesCodeFunc = function(self, wanted) return 0 end
    item.OnLeftClickFunc = function(self) marks[name] = not marks[name] or nil; HuntRefresh() end
    item.OnRightClickFunc = function(self) marks[name] = nil; HuntRefresh() end
    item.SaveFunc = function(self) return {marked = marks[name] == true} end
    item.LoadFunc = function(self, data)
        marks[name] = type(data) == "table" and data.marked == true or nil
        HuntRefresh()
    end
    cards[name] = item
end

local function hunt_key()
    return "ffcc_hunt_" .. Archipelago.TeamNumber .. "_" .. Archipelago.PlayerNumber
end

local function on_records(key, value)
    if key ~= hunt_key() then return end
    defeated = {}
    if type(value) == "table" then
        for enemy, on in pairs(value) do
            if on then defeated[enemy] = true end
        end
    end
    HuntRefresh()
end

if Archipelago and Archipelago.AddSetReplyHandler then
    Archipelago:AddClearHandler("monster hunt", function(slot_data)
        local mode = slot_data and slot_data["monster_hunt_checks"]
        HUNT_MODE = mode == true and 1 or tonumber(mode) or 0
        defeated = {}
        Archipelago:SetNotify({hunt_key()})
        Archipelago:Get({hunt_key()})
        HuntRefresh()
    end)
    Archipelago:AddRetrievedHandler("monster hunt", on_records)
    Archipelago:AddSetReplyHandler("monster hunt", function(key, value) on_records(key, value) end)
end

-- what is in logic changes with every item, so the card borders follow
ScriptHost:AddWatchForCode("monster hunt logic", "*", function(code) HuntRefresh() end)

HuntRefresh()
